# ---- attrcsat.profile ----
import math
from datetime import date, datetime


_PF_KIND_WEIGHTS = (("N_DEPOSIT", 0.20), ("N_LOAN", 0.25), ("N_INVESTMENT", 0.30), ("N_LINE", 0.25))


def _pf_rng(account_id: str, field: str):
    return stable_rng(account_id, "attrcsat-" + field)


# CLIENT_CATEGORY decides the kind; ACCOUNT_TYPE_FLAG (= BIRTHDATE IS NOT NULL in V_ACCOUNT_ANCHORS)
# is only the fallback for an unknown or empty category, since persons without a birthdate carry 'BUSINESS'.
_PF_PERSON_CATEGORIES = ("retail", "wealthmanagement", "gold", "silver", "bronze", "platinum")
_PF_BUSINESS_CATEGORIES = ("smallbusiness", "commercialbanking", "corporate", "commercial", "business")


def _pf_category(feature: dict) -> str:
    """Compact CLIENT_CATEGORY ('Wealth Management' live -> 'WealthManagement'), the form downstream keys on."""
    return "".join(str(feature.get("CLIENT_CATEGORY") or "").split())


def _pf_kind(feature: dict) -> str:
    cat = _pf_category(feature).lower()
    if cat == "household":
        return "HOUSEHOLD"
    if cat in _PF_BUSINESS_CATEGORIES:
        return "BUSINESS"
    if cat in _PF_PERSON_CATEGORIES:
        return "PERSON"
    if str(feature.get("ACCOUNT_TYPE_FLAG") or "").upper() == "PERSON":
        return "PERSON"
    return "BUSINESS"


def _pf_months_between(start: date, end: date) -> int:
    months = (end.year - start.year) * 12 + (end.month - start.month)
    if end.day < start.day:
        months -= 1
    return max(0, months)


def _pf_age(feature: dict, kind: str, anchor: date, aid: str) -> int:
    born = as_date(feature.get("BIRTHDATE"))
    if kind == "PERSON" and born is not None:
        age = anchor.year - born.year - ((anchor.month, anchor.day) < (born.month, born.day))
        return max(0, age)
    rng = _pf_rng(aid, "age")
    if kind == "PERSON":
        return rng.randint(25, 78)
    return rng.randint(30, 72)


def _pf_income(feature: dict, kind: str, aid: str) -> float:
    inc = as_float(feature.get("ANNUAL_INCOME"))
    rev = as_float(feature.get("ANNUAL_REVENUE"))
    order = (rev, inc) if kind == "BUSINESS" else (inc, rev)
    for v in order:
        if v is not None and v > 0:
            return v
    rng = _pf_rng(aid, "income")
    if kind == "PERSON":
        return round(rng.uniform(40000, 160000), 2)
    if kind == "HOUSEHOLD":
        return round(rng.uniform(90000, 400000), 2)
    return round(rng.uniform(300000, 8000000), 2)


def _pf_credit(feature: dict, kind: str, income: float, aid: str) -> float:
    cs = as_float(feature.get("CREDIT_SCORE"))
    if cs is not None:
        return cs
    base = _pf_rng(aid, "credit").uniform(640, 820)
    if kind == "BUSINESS":
        # larger revenue skews the score higher, up to about +25 points
        base += clamp((math.log10(max(income, 1.0)) - 5.5) * 12, 0, 25)
    return round(base, 1)


def _pf_holdings(feature: dict, aid: str) -> tuple[int, dict]:
    """(n_products, {kind-column: count}); seeded when the feed has no holdings."""
    n = as_float(feature.get("N_PRODUCTS"))
    cols = [c for c, _ in _PF_KIND_WEIGHTS]
    counts = {c: as_float(feature.get(c)) for c in cols}
    if n is not None:
        have = {c: int(v or 0) for c, v in counts.items()}
        return max(1, int(n)), have
    rng = _pf_rng(aid, "n_products")
    n_prod = rng.randint(1, 3)
    have = {c: 0 for c in cols}
    have["N_DEPOSIT"] = 1
    extra = [c for c in cols if c != "N_DEPOSIT"]
    rng.shuffle(extra)
    for c in extra[: n_prod - 1]:
        have[c] = 1
    return n_prod, have


def _pf_nps_category(feature: dict, aid: str) -> str:
    desc = str(feature.get("NPS_DESCRIPTION") or "").strip().lower()
    if desc.startswith("promoter"):
        return "Promoter"
    if desc.startswith("passive"):
        return "Passive"
    if desc.startswith("detractor"):
        return "Detractor"
    score = as_float(feature.get("NPS_SCORE"))
    if score is not None:
        return "Promoter" if score >= 9 else ("Passive" if score >= 7 else "Detractor")
    r = _pf_rng(aid, "nps").random()
    return "Promoter" if r < 0.35 else ("Passive" if r < 0.75 else "Detractor")


def _pf_risk(feature: dict) -> str:
    if any(bool(feature.get(k)) for k in ("SANCTIONS_HIT", "PEP_HIT", "ADVERSE_MEDIA_HIT")):
        return "REVIEW"
    rating = str(feature.get("RISK_RATING") or "Low").strip().lower()
    if rating in ("high", "severe"):
        return "REVIEW"
    if rating == "medium":
        return "WATCH"
    return "CLEAN"


def build_profile(feature: dict, run_ts: datetime) -> dict:
    aid = str(feature["ACCOUNT_ID"])
    kind = _pf_kind(feature)
    anchor = date(run_ts.year, run_ts.month, 1)
    grounded = feature.get("N_PRODUCTS") is not None

    age = _pf_age(feature, kind, anchor, aid)
    income = _pf_income(feature, kind, aid)
    credit = _pf_credit(feature, kind, income, aid)

    opened = as_date(feature.get("FIRST_OPEN_DATE"))
    if opened is not None:
        tenure = _pf_months_between(opened, anchor)
    else:
        tenure = _pf_rng(aid, "tenure").randint(12, 240)

    n_products, held = _pf_holdings(feature, aid)

    dd = as_float(feature.get("DD_AMOUNT"))
    if dd is not None:
        has_dd = dd > 0
    else:
        has_dd = _pf_rng(aid, "direct_deposit").random() < (0.55 if kind == "PERSON" else 0.20)
    bonus = as_float(feature.get("BONUS_AMOUNT"))
    if bonus is not None:
        has_promo = bonus > 0
    else:
        has_promo = _pf_rng(aid, "promo").random() < 0.30

    total = as_float(feature.get("TOTAL_BALANCE"))
    avg = as_float(feature.get("AVG_BALANCE"))
    if total is None and avg is None:
        total = max(100.0, income * 0.25 * math.exp(_pf_rng(aid, "balance").gauss(0, 0.5)))
        avg = total
    elif total is None:
        total = avg
    elif avg is None:
        avg = total

    early = as_float(feature.get("EARLY_AVG_BALANCE"))
    late = as_float(feature.get("LATE_AVG_BALANCE"))
    if early is not None and late is not None:
        drop = (early - late) / early if early > 0 and late < early else 0.0
    else:
        r = _pf_rng(aid, "balance_drop")
        drop = r.uniform(0.0, 0.15) if r.random() < 0.3 else 0.0
    drop = round(drop, 4)

    adb_txn = as_float(feature.get("ADB_TXN"))
    adb_days = as_float(feature.get("ADB_DAYS"))
    ft_txn = as_float(feature.get("FT_TXN"))
    if adb_txn is not None and adb_days:
        monthly_txn = adb_txn / adb_days * 30
    elif ft_txn is not None:
        monthly_txn = ft_txn
    else:
        monthly_txn = _pf_rng(aid, "monthly_txn").uniform(2, 30)

    credits = as_float(feature.get("CREDITS"))
    debits = as_float(feature.get("DEBITS"))
    if credits is not None and credits > 0 and debits is not None:
        savings = max(0.0, (credits - debits) / credits)
    else:
        savings = _pf_rng(aid, "savings_rate").uniform(0.02, 0.12)

    calls = as_float(feature.get("CALLS"))
    weeks = as_float(feature.get("GONG_WEEKS"))
    if calls is not None and weeks is not None:
        monthly_calls = calls / max(weeks, 1.0) * 4.33
    else:
        monthly_calls = _pf_rng(aid, "monthly_calls").uniform(0.3, 2.0)
    last_call = as_date(feature.get("LAST_CALL_DATE"))
    if last_call is not None:
        days_since = max(0, (anchor - last_call).days)
    else:
        days_since = _pf_rng(aid, "days_since").randint(20, 90)

    neg_weeks = int(as_float(feature.get("NEG_WEEKS")) or 0)
    complaints = int(as_float(feature.get("DETRACTOR_12M")) or 0) + neg_weeks // 4
    escalations = int(as_float(feature.get("VNEG_WEEKS")) or 0)

    breadth = sum(w for c, w in _PF_KIND_WEIGHTS if held.get(c, 0) > 0)
    jit = _pf_rng(aid, "cross_sell").uniform(-0.02, 0.02)
    cross_sell = clamp(0.7 * breadth + 0.25 * min(n_products, 8) / 8 + jit, 0.0, 1.0)

    z = -0.06 * (age - 50) + 0.02 * (monthly_txn - 15)
    if kind == "BUSINESS":
        z += 0.6
    elif kind == "HOUSEHOLD":
        z -= 0.5
    digital = 1.0 / (1.0 + math.exp(-z))

    return {
        "account_id": aid,
        "kind": kind,
        "client_category": _pf_category(feature),
        "age": int(age),
        "income": float(income),
        "credit_score": float(credit),
        "tenure_months": int(tenure),
        "n_products": int(n_products),
        "has_direct_deposit": bool(has_dd),
        "has_promo": bool(has_promo),
        "total_balance": float(total),
        "avg_balance": float(avg),
        "pct_balance_drop": float(drop),
        "monthly_txn": float(monthly_txn),
        "savings_rate": float(savings),
        "monthly_calls": float(monthly_calls),
        "days_since_interaction": int(days_since),
        "complaints": int(complaints),
        "escalations": int(escalations),
        "nps_category": _pf_nps_category(feature, aid),
        "cross_sell": float(cross_sell),
        "risk": _pf_risk(feature),
        "digital_affinity": float(clamp(digital, 0.0, 1.0)),
        "grounded": bool(grounded),
    }


# ---- attrcsat.checks ----
_CK_TABLES = {
    "ATTRITION": (ATTRITION_COLUMNS, "UNIQUEID", {}),
    "CSAT": (CSAT_COLUMNS, "ACCOUNTID", {"CROSS_SELL_SCORE": "CSAT.CROSS_SELL_SCORE"}),
    "ENROLLMENTS": (ENROLLMENT_COLUMNS, "ACCOUNTID",
                    {"CROSS_SELL_SCORE": "ENR.CROSS_SELL_SCORE", "SAVINGS_RATE": "ENR.SAVINGS_RATE"}),
}
_CK_ATT_TOL = 0.17
_CK_CSAT_TOL = 0.12


def row_problems(table: str, row: dict) -> list[str]:
    """Violations for one row (empty = pass): columns, NULLs, key prefix, vocabulary, ranges, booleans."""
    columns, key, range_keys = _CK_TABLES[table]
    rid = str(row.get(key))
    out: list[str] = []
    if tuple(row) != columns:
        out.append(f"{rid}: {table} columns differ from contract")
    for c in columns:
        v = row.get(c)
        if v is None:
            out.append(f"{rid}: {c} is NULL")
            continue
        if c in CATEGORIES and v not in CATEGORIES[c]:
            out.append(f"{rid}: {c}={v!r} outside vocabulary")
        if c in BOOL_COLUMNS and not isinstance(v, bool):
            out.append(f"{rid}: {c} is not a boolean")
        rng = RANGES.get(range_keys.get(c, c))
        if rng is not None and c not in CATEGORIES:
            if isinstance(v, bool) or not isinstance(v, (int, float)) or not (rng[0] <= v <= rng[1]):
                out.append(f"{rid}: {c}={v!r} outside [{rng[0]}, {rng[1]}]")
    if not rid.startswith("001am"):
        out.append(f"{rid}: {key} does not start with 001am")
    return out


def cross_table_problems(att: list, csat: list, enr: list) -> list[str]:
    """Agreement between the three tables for the same customer (lists aligned by account)."""
    if not (len(att) == len(csat) == len(enr)):
        return [f"table length mismatch: {len(att)}/{len(csat)}/{len(enr)}"]
    out: list[str] = []
    for a, c, e in zip(att, csat, enr):
        aid = e["ACCOUNTID"]
        if not (a["UNIQUEID"] == c["ACCOUNTID"] == aid):
            out.append(f"{aid}: account ids differ across tables")
            continue
        for col, flag in (("ONLINE_BANKING_C", "ONLINE_ENROLLED"), ("MOBILE_BANKING_C", "MOBILE_ENROLLED")):
            if (a[col] == "Yes") != bool(e[flag]):
                out.append(f"{aid}: {col}={a[col]} disagrees with {flag}={e[flag]}")
        enr_x = (e["CROSS_SELL_SCORE"] - 1) / 9
        if abs((a["CROSS_SELL_SCORE_C"] - 1) / 6 - enr_x) > _CK_ATT_TOL:
            out.append(f"{aid}: attrition cross-sell disagrees with enrollment")
        if abs(c["CROSS_SELL_SCORE"] / 100 - enr_x) > _CK_CSAT_TOL:
            out.append(f"{aid}: CSAT cross-sell disagrees with enrollment")
    return out


# ---- attrcsat.enrollments ----
import math
from datetime import datetime


_EN_EPOCH = 2026 * 12  # month index of 2026-01; change months are counted from here
_EN_ENROL_P = 0.004    # monthly hazard for False -> True
_EN_UNENROL_P = 0.0015  # monthly hazard for True -> False
_EN_LOW_WIRE_P = 0.10  # cohorts below this base rate never drift toward wire-enabled
_EN_YOUNG_AGE = 25
_EN_WIRE_BALANCE = 250000
_EN_RETAIL_WIRE_CAP = 0.06  # book-level cap on the Retail-person wire rate
_EN_RETAIL_WIRE_MIN_N = 1000  # the cap is only meaningful on a book with at least this many Retail persons
_EN_REVIEW_STATUS = ("Under Review", "Pending")
_EN_REVIEW_KYC_CLEAN = ("Current", "Expired")
_EN_REVIEW_AML_CLEAN = ("Cleared", "None")


def _en_draw(aid: str, flag: str) -> float:
    return stable_rng(aid, "attrcsat-enr-" + flag).random()


def _en_month_index(run_ts: datetime) -> int:
    return run_ts.year * 12 + run_ts.month - 1


def _en_change_month(aid: str, flag: str, base: bool) -> int:
    """Month index at which the flag flips from base (geometric, drawn once per account and flag)."""
    p = _EN_UNENROL_P if base else _EN_ENROL_P
    u = stable_rng(aid, "attrcsat-chg-" + flag).random()
    return _EN_EPOCH + 1 + int(math.log(1.0 - u) / math.log(1.0 - p))


def _en_changed(aid: str, flag: str, base: bool, month: int) -> bool:
    return month >= _en_change_month(aid, flag, base)


def _en_young_retail(p: dict) -> bool:
    """Young, non-wealth, modest-balance persons (students, first jobs) never have wires enabled."""
    return (p["kind"] == "PERSON" and p["age"] < _EN_YOUNG_AGE and p["client_category"] != "WealthManagement"
            and p["total_balance"] < _EN_WIRE_BALANCE)


def _en_wire_p(p: dict) -> float:
    if _en_young_retail(p):
        return 0.0
    rich = p["total_balance"] >= _EN_WIRE_BALANCE
    if p["kind"] == "BUSINESS":
        base = 0.6
    elif p["kind"] == "HOUSEHOLD":
        base = 0.15
    elif p["client_category"] == "WealthManagement":
        base = 0.35
    else:
        # other persons stay under _EN_LOW_WIRE_P even when rich: no drift on, and the Retail cap holds
        return 0.05 if rich else 0.03
    return base + (0.1 if rich else 0.0)


def _en_status(aid: str, salt: str, options: tuple, weights: tuple) -> str:
    u = stable_rng(aid, "attrcsat-enr-" + salt).random()
    acc = 0.0
    for opt, w in zip(options, weights):
        acc += w
        if u < acc:
            return opt
    return options[-1]


def _en_kyc_aml(p: dict) -> tuple[str, str]:
    aid = p["account_id"]
    if p["risk"] == "REVIEW":
        return (_en_status(aid, "kyc", _EN_REVIEW_STATUS, (0.5, 0.5)),
                _en_status(aid, "aml", _EN_REVIEW_STATUS, (0.5, 0.5)))
    if p["risk"] == "WATCH":
        return (_en_status(aid, "kyc", ("Current", "Pending"), (0.7, 0.3)),
                _en_status(aid, "aml", ("Cleared", "Pending"), (0.6, 0.4)))
    return (_en_status(aid, "kyc", ("Expired", "Current"), (0.05, 0.95)),
            _en_status(aid, "aml", ("None", "Cleared"), (0.03, 0.97)))


def enrollment_row(profile: dict, run_ts: datetime) -> dict:
    aid = profile["account_id"]
    month = _en_month_index(run_ts)
    aff = profile["digital_affinity"]
    online_p = clamp(0.55 + 0.35 * aff + (0.1 if profile["kind"] == "BUSINESS" else 0.0), 0.0, 1.0)
    mobile_p = clamp(0.15 + 0.75 * aff, 0.0, 1.0)

    def drift(col: str, base: bool, allow: bool = True) -> bool:
        return base != (allow and _en_changed(aid, col, base, month))

    # Base state (month-independent). Paperless/alerts thresholds follow the base digital state.
    online0 = _en_draw(aid, "online") < online_p
    mobile0 = _en_draw(aid, "mobile") < mobile_p
    digital0 = online0 or mobile0
    mfa0 = _en_draw(aid, "mfa") < 0.85 and digital0
    paperless0 = _en_draw(aid, "paperless") < (0.6 if digital0 else 0.05)
    alerts0 = _en_draw(aid, "alerts") < (0.65 if digital0 else 0.05)
    wire_p = _en_wire_p(profile)
    wire0 = _en_draw(aid, "wire") < wire_p

    # Digital never goes True -> False: an account keeps at least one channel, so when both are on only the
    # channel with the earlier change month may un-enrol; a sole channel never un-enrols.
    if online0 and mobile0:
        first = ("ONLINE_ENROLLED" if _en_change_month(aid, "ONLINE_ENROLLED", True)
                 <= _en_change_month(aid, "MOBILE_ENROLLED", True) else "MOBILE_ENROLLED")
        online = drift("ONLINE_ENROLLED", online0, first == "ONLINE_ENROLLED")
        mobile = drift("MOBILE_ENROLLED", mobile0, first == "MOBILE_ENROLLED")
    else:
        online = drift("ONLINE_ENROLLED", online0, not online0)
        mobile = drift("MOBILE_ENROLLED", mobile0, not mobile0)
    digital = online or mobile
    # digital is constant (base on) or only switches on (base off), so MFA = pref and digital stays
    # monotone as long as pref moves the same way: with digital off at base, pref may only switch on.
    mfa_pref0 = _en_draw(aid, "mfa") < 0.85
    if digital0:
        mfa = drift("MFA_STATUS", mfa0)
    else:
        mfa = drift("MFA_STATUS", mfa_pref0, not mfa_pref0) and digital
    # Paperless/alerts follow digital: with digital off at base they may only switch on once digital is on
    # (both monotone, so the AND is too); with digital on at base they drift either way.
    if digital0:
        paperless = drift("PAPERLESS_ENROLLED", paperless0)
        alerts = drift("ALERT_ENROLLED", alerts0)
    else:
        paperless = paperless0 if paperless0 else (drift("PAPERLESS_ENROLLED", False) and digital)
        alerts = alerts0 if alerts0 else (drift("ALERT_ENROLLED", False) and digital)
    # low-wire cohorts (young retail included) never drift on, so their rate stays within the cap
    wire = drift("WIRE_ENABLED", wire0, wire0 or wire_p >= _EN_LOW_WIRE_P)
    flags = {
        "ONLINE_ENROLLED": online, "MOBILE_ENROLLED": mobile, "MFA_STATUS": mfa,
        "PAPERLESS_ENROLLED": paperless, "ALERT_ENROLLED": alerts, "WIRE_ENABLED": wire,
    }

    kyc, aml = _en_kyc_aml(profile)
    row = {
        "ACCOUNTID": aid,
        "MOBILE_ENROLLED": flags["MOBILE_ENROLLED"],
        "ONLINE_ENROLLED": flags["ONLINE_ENROLLED"],
        "KYC_STATUS": kyc,
        "MFA_STATUS": flags["MFA_STATUS"],
        "PAPERLESS_ENROLLED": flags["PAPERLESS_ENROLLED"],
        "ALERT_ENROLLED": flags["ALERT_ENROLLED"],
        "WIRE_ENABLED": flags["WIRE_ENABLED"],
        "SAVINGS_RATE": round(clamp(profile["savings_rate"], 0.0, 0.40), 2),
        "CROSS_SELL_SCORE": 1 + round(9 * profile["cross_sell"]),
        "AML_STATUS": aml,
        "SNAPSHOT_DATE": f"{run_ts:%Y-%m}-01 00:00:00",
    }
    return {c: row[c] for c in ENROLLMENT_COLUMNS}


def enrollment_problems(rows: list[dict], profiles: list[dict]) -> list[str]:
    """Human-readable violations (empty = pass). rows and profiles are parallel lists."""
    out: list[str] = []
    if len(rows) != len(profiles):
        return [f"row/profile length mismatch: {len(rows)} vs {len(profiles)}"]
    for r, p in zip(rows, profiles):
        aid = str(r.get("ACCOUNTID"))
        out.extend(row_problems("ENROLLMENTS", r))
        if r.get("MFA_STATUS") is True and not (r.get("ONLINE_ENROLLED") or r.get("MOBILE_ENROLLED")):
            out.append(f"{aid}: MFA_STATUS true but neither online nor mobile enrolled")
        kyc, aml = r.get("KYC_STATUS"), r.get("AML_STATUS")
        if p["risk"] == "REVIEW":
            if kyc in _EN_REVIEW_KYC_CLEAN:
                out.append(f"{aid}: REVIEW profile has clean KYC_STATUS {kyc}")
            if aml in _EN_REVIEW_AML_CLEAN:
                out.append(f"{aid}: REVIEW profile has clean AML_STATUS {aml}")
        elif p["risk"] == "CLEAN":
            if kyc in _EN_REVIEW_STATUS:
                out.append(f"{aid}: CLEAN profile has review KYC_STATUS {kyc}")
            if aml in _EN_REVIEW_STATUS:
                out.append(f"{aid}: CLEAN profile has review AML_STATUS {aml}")
        if r.get("WIRE_ENABLED") is True and _en_young_retail(p):
            out.append(f"{aid}: WIRE_ENABLED on a young non-wealth person under {_EN_YOUNG_AGE}")
    retail = [r for r, p in zip(rows, profiles) if p["kind"] == "PERSON" and p["client_category"] == "Retail"]
    if len(retail) >= _EN_RETAIL_WIRE_MIN_N:
        rate = sum(1 for r in retail if r.get("WIRE_ENABLED") is True) / len(retail)
        if rate > _EN_RETAIL_WIRE_CAP:
            out.append(f"Retail-person wire rate {rate:.3f} above cap {_EN_RETAIL_WIRE_CAP}")
    return out


# ---- attrcsat.attrition ----
_AT_PREFERRED = ("WealthManagement", "Gold", "Platinum")
_AT_PREMIUM = ("CommercialBanking", "Silver")


def _at_int(col: str, value: float) -> int:
    lo, hi = RANGES[col]
    return int(clamp(round(value), lo, hi))


def _at_dec(col: str, value: float) -> float:
    lo, hi = RANGES[col]
    return round(clamp(value, lo, hi), 2)


def _at_yn(flag) -> str:
    return "Yes" if flag else "No"


def _at_segment(p: dict) -> str:
    cat, bal = p["client_category"], p["total_balance"]
    if cat in _AT_PREFERRED or bal >= 250000:
        return "Preferred"
    if cat in _AT_PREMIUM or bal >= 75000:
        return "Premium"
    return "Regular"


def attrition_row(profile: dict, enrollment: dict) -> dict:
    p = profile
    row = {
        "CUSTOMER_SEGMENT_C": _at_segment(p),
        "CROSS_SELL_SCORE_C": _at_int("CROSS_SELL_SCORE_C", 1 + round(6 * p["cross_sell"])),
        "ONLINE_BANKING_C": _at_yn(enrollment["ONLINE_ENROLLED"]),
        "MOBILE_BANKING_C": _at_yn(enrollment["MOBILE_ENROLLED"]),
        "DIRECT_DEPOSIT_C": _at_yn(p["has_direct_deposit"]),
        "AVG_NUMBER_OF_TRANSACTIONS_C": _at_int("AVG_NUMBER_OF_TRANSACTIONS_C", p["monthly_txn"]),
        "TENURE_IN_MONTHS_C": _at_int("TENURE_IN_MONTHS_C", p["tenure_months"]),
        "AVG_BALANCE_6_MONTHS_C": _at_dec("AVG_BALANCE_6_MONTHS_C", p["avg_balance"]),
        "NPS_SCORE_C": p["nps_category"],
        "SINGLE_PRODUCT_CUSTOMER_C": _at_yn(p["n_products"] == 1),
        "PROMOTIONAL_PRODUCT_C": _at_yn(p["has_promo"]),
        "PCT_BALANCE_DROP_6_MONTHS_AVG_C": _at_dec("PCT_BALANCE_DROP_6_MONTHS_AVG_C", p["pct_balance_drop"]),
        "DAYS_SINCE_LAST_INTERACTION_C": _at_int("DAYS_SINCE_LAST_INTERACTION_C", p["days_since_interaction"]),
        "CHURNED_C": "No",
        "UNIQUEID": p["account_id"],
        "AVG_NUMBER_OF_CALL_CENTER_CALLS_C": _at_int("AVG_NUMBER_OF_CALL_CENTER_CALLS_C", p["monthly_calls"]),
    }
    return {c: row[c] for c in ATTRITION_COLUMNS}


# ---- attrcsat.csat ----
_CS_WEALTH = ("WealthManagement", "Gold", "Platinum")


def _cs_int(col: str, value: float, key: str | None = None) -> int:
    lo, hi = RANGES[key or col]
    return int(clamp(round(value), lo, hi))


def _cs_dec(col: str, value: float) -> float:
    lo, hi = RANGES[col]
    return round(clamp(value, lo, hi), 2)


def _cs_segment(p: dict) -> str:
    if p["kind"] == "BUSINESS":
        return "Corporate" if p["client_category"] == "CommercialBanking" else "Commercial"
    if p["kind"] == "PERSON" and p["client_category"] in _CS_WEALTH:
        return "WealthManagement"
    return "Banking"


def csat_row(profile: dict, enrollment: dict) -> dict:
    p = profile
    share = sum(1 for c in BOOL_COLUMNS if enrollment[c] is True) / len(BOOL_COLUMNS)
    engagement = 40 + 59 * (p["digital_affinity"] + share) / 2
    row = {
        "SEGMENT": _cs_segment(p),
        "AGE": _cs_int("AGE", p["age"]),
        "ANNUAL_INCOME": _cs_int("ANNUAL_INCOME", p["income"]),
        "ACCOUNT_BALANCE": _cs_dec("ACCOUNT_BALANCE", p["total_balance"]),
        "TENURE_YEARS": _cs_int("TENURE_YEARS", p["tenure_months"] / 12),
        "NUM_PRODUCTS": _cs_int("NUM_PRODUCTS", p["n_products"]),
        "DIGITAL_ENGAGEMENT": _cs_dec("DIGITAL_ENGAGEMENT", engagement),
        "COMPLAINT_COUNT": _cs_int("COMPLAINT_COUNT", p["complaints"]),
        "CUSTOMER_SERVICE_CONTACT": _cs_int("CUSTOMER_SERVICE_CONTACT", p["monthly_calls"]),
        "CROSS_SELL_SCORE": _cs_int("CROSS_SELL_SCORE", 100 * p["cross_sell"], "CSAT.CROSS_SELL_SCORE"),
        "ESCALATED_CASES": _cs_int("ESCALATED_CASES", p["escalations"]),
        "TRANSACTION_VOLUME": _cs_int("TRANSACTION_VOLUME", p["monthly_txn"]),
        "CREDIT_SCORE": _cs_dec("CREDIT_SCORE", p["credit_score"]),
        "ACCOUNTID": p["account_id"],
    }
    return {c: row[c] for c in CSAT_COLUMNS}


# ---- attrcsat.sp_main ----
import uuid
from datetime import datetime, timezone


TASK_NAME = "TASK_MONTHLY_ATTRITION_CSAT_INPUTS"

_sp_DB = "DATA_JEDAIS"
_sp_SCHEMA = "FINS__PUBLIC"
_sp_PREFIX = f"{_sp_DB}.{_sp_SCHEMA}"
_sp_ATT = f"{_sp_PREFIX}.ATTRITION_INPUTS"
_sp_CSAT = f"{_sp_PREFIX}.CSAT_ATTRITION_INPUTS"
_sp_ENR = f"{_sp_PREFIX}.ENROLLMENTS"
_sp_MODES = ("INPUTS",)

# Audience: every 001am anchor (households included), one row per ACCOUNT_ID.
_sp_AUD = f"""aud AS (
  SELECT ACCOUNT_ID, ACCOUNT_TYPE_FLAG, CLIENT_CATEGORY, BIRTHDATE, ANNUAL_INCOME, ANNUAL_REVENUE, CREDIT_SCORE
  FROM {_sp_PREFIX}.V_ACCOUNT_ANCHORS
  WHERE ACCOUNT_ID LIKE '001am%'
  QUALIFY ROW_NUMBER() OVER (PARTITION BY ACCOUNT_ID ORDER BY SNAPSHOT_DATE DESC NULLS LAST) = 1
)"""

# Feed windows end at the run month's first day (exclusive): re-runs inside a month read the same data.
_sp_ANCHOR = "DATE_TRUNC('month', CURRENT_DATE())"

# Deposit and investment products hold customer wealth; loans and lines (cards) are liabilities.
_sp_WEALTH_KINDS = "PRODUCT_KIND IN ('deposit', 'investment')"

FEATURES_SQL = f"""WITH {_sp_AUD},
nps AS (
  SELECT ACCOUNTID AS ACCOUNT_ID, NPS_SCORE, NPS_DESCRIPTION,
         COUNT_IF(NPS_SCORE <= 6 AND SCORE_DATE >= DATEADD(month, -12, {_sp_ANCHOR}))
           OVER (PARTITION BY ACCOUNTID) AS DETRACTOR_12M
  FROM {_sp_PREFIX}.CSAT_NPS_DATA
  WHERE SCORE_DATE < {_sp_ANCHOR}
  QUALIFY ROW_NUMBER() OVER (PARTITION BY ACCOUNTID ORDER BY SCORE_DATE DESC, ROWID DESC) = 1
),
fta_raw AS (
  SELECT * FROM {_sp_PREFIX}.FINANCIAL_TRANSACTION_ACCOUNTS WHERE COALESCE(ACTIVE, TRUE)
),
fta AS (
  SELECT SFACCOUNTID AS ACCOUNT_ID,
         COUNT(DISTINCT ACCOUNTID) AS N_PRODUCTS,
         COUNT_IF(PRODUCT_KIND = 'deposit') AS N_DEPOSIT,
         COUNT_IF(PRODUCT_KIND = 'loan') AS N_LOAN,
         COUNT_IF(FINANCIAL_ACCOUNT_TYPE = 'Investments') AS N_INVESTMENT,
         COUNT_IF(PRODUCT_KIND = 'line') AS N_LINE,
         SUM(DIRECT_DEPOSIT_AMOUNT) AS DD_AMOUNT,
         SUM(BONUS_AMOUNT) AS BONUS_AMOUNT,
         MIN(OPEN_DATE) AS FIRST_OPEN_DATE,
         SUM(IFF({_sp_WEALTH_KINDS}, COALESCE(BALANCE, 0), 0)) AS TOTAL_BALANCE
  FROM fta_raw GROUP BY 1
),
fta_map AS (
  SELECT DISTINCT ACCOUNTID, SFACCOUNTID AS ACCOUNT_ID, {_sp_WEALTH_KINDS} AS IS_WEALTH FROM fta_raw
),
adb_acct AS (
  -- ADB rows exist only on transacting days: average each financial account over its own rows first.
  SELECT m.ACCOUNT_ID, b.ACCOUNTID, m.IS_WEALTH,
         AVG(b.CLOSING_BALANCE) AS ACCT_AVG,
         AVG(IFF(b.BALANCE_DATE < DATEADD(month, -3, {_sp_ANCHOR}), b.CLOSING_BALANCE, NULL)) AS ACCT_EARLY,
         AVG(IFF(b.BALANCE_DATE >= DATEADD(month, -3, {_sp_ANCHOR}), b.CLOSING_BALANCE, NULL)) AS ACCT_LATE,
         SUM(b.DAILY_CREDITS) AS CR, SUM(b.DAILY_DEBITS) AS DR, SUM(b.TRANSACTION_COUNT) AS TXN
  FROM {_sp_PREFIX}.ACCOUNT_DAILY_BALANCE b JOIN fta_map m ON b.ACCOUNTID = m.ACCOUNTID
  WHERE b.BALANCE_DATE >= DATEADD(month, -6, {_sp_ANCHOR}) AND b.BALANCE_DATE < {_sp_ANCHOR}
  GROUP BY m.ACCOUNT_ID, b.ACCOUNTID, m.IS_WEALTH
),
adb AS (
  SELECT ACCOUNT_ID,
         SUM(IFF(IS_WEALTH, ACCT_AVG, NULL)) AS AVG_BALANCE,
         SUM(IFF(IS_WEALTH AND ACCT_EARLY IS NOT NULL AND ACCT_LATE IS NOT NULL, ACCT_EARLY, NULL))
           AS EARLY_AVG_BALANCE,
         SUM(IFF(IS_WEALTH AND ACCT_EARLY IS NOT NULL AND ACCT_LATE IS NOT NULL, ACCT_LATE, NULL))
           AS LATE_AVG_BALANCE,
         SUM(IFF(IS_WEALTH, CR, NULL)) AS CREDITS, SUM(IFF(IS_WEALTH, DR, NULL)) AS DEBITS,
         SUM(TXN) AS ADB_TXN,
         ANY_VALUE(DATEDIFF(day, DATEADD(month, -6, {_sp_ANCHOR}), {_sp_ANCHOR})) AS ADB_DAYS
  FROM adb_acct GROUP BY 1
),
ft AS (
  SELECT SFACCOUNTID AS ACCOUNT_ID, COUNT(*) AS FT_TXN
  FROM {_sp_PREFIX}.FINANCIAL_TRANSACTIONS
  WHERE POSTINGDATE >= DATEADD(day, -30, {_sp_ANCHOR}) AND POSTINGDATE < {_sp_ANCHOR}
  GROUP BY 1
),
gong AS (
  SELECT ACCOUNT_ID, SUM(CALL_COUNT_LAST_7D) AS CALLS, COUNT(*) AS GONG_WEEKS, MAX(LAST_CALL_DATE) AS LAST_CALL_DATE,
         COUNT_IF(OVERALL_SENTIMENT IN ('Negative', 'Very Negative')) AS NEG_WEEKS,
         COUNT_IF(OVERALL_SENTIMENT = 'Very Negative') AS VNEG_WEEKS
  FROM {_sp_PREFIX}.GONG_CALL_SENTIMENT
  WHERE PROFILE_WEEK >= DATEADD(week, -12, {_sp_ANCHOR}) AND PROFILE_WEEK < {_sp_ANCHOR}
  GROUP BY 1
),
wc AS (
  SELECT ACCOUNT_ID, OVERALL_RISK_RATING AS RISK_RATING, SANCTIONS_HIT, PEP_HIT, ADVERSE_MEDIA_HIT
  FROM {_sp_PREFIX}.WORLD_CHECK_AML
  WHERE PROFILE_DATE < {_sp_ANCHOR}
  QUALIFY ROW_NUMBER() OVER (PARTITION BY ACCOUNT_ID
                             ORDER BY PROFILE_DATE DESC, LAST_SCREENED_AT DESC, GENERATED_AT DESC, ORG_ID) = 1
)
SELECT aud.*, nps.* EXCLUDE (ACCOUNT_ID), fta.* EXCLUDE (ACCOUNT_ID), adb.* EXCLUDE (ACCOUNT_ID),
       ft.* EXCLUDE (ACCOUNT_ID), gong.* EXCLUDE (ACCOUNT_ID), wc.* EXCLUDE (ACCOUNT_ID)
FROM aud LEFT JOIN nps USING (ACCOUNT_ID) LEFT JOIN fta USING (ACCOUNT_ID) LEFT JOIN adb USING (ACCOUNT_ID)
     LEFT JOIN ft USING (ACCOUNT_ID) LEFT JOIN gong USING (ACCOUNT_ID) LEFT JOIN wc USING (ACCOUNT_ID)"""


def _sp_to_dict(row) -> dict:
    """Snowpark Row -> plain dict (dicts pass through)."""
    if isinstance(row, dict):
        return row
    if hasattr(row, "asDict"):
        return dict(row.asDict())
    return dict(row)


def dedupe_anchors(rows: list[dict]) -> list[dict]:
    """Python backstop on ACCOUNT_ID: keep the first row per account."""
    seen: set = set()
    out = []
    for r in rows:
        k = r["ACCOUNT_ID"]
        if k in seen:
            continue
        seen.add(k)
        out.append(r)
    return out


def _sp_build_all(features: list[dict], run_ts):
    """One profile list drives all three tables, so the lists are aligned by index.
    Zero tolerance: any row-factory exception raises with the first few account ids."""
    profiles, att, csat, enr, errors = [], [], [], [], []
    for f in features:
        try:
            p = build_profile(f, run_ts)
            e = enrollment_row(p, run_ts)
            a = attrition_row(p, e)
            c = csat_row(p, e)
        except Exception as exc:  # noqa: BLE001 - collected and raised together
            errors.append((f.get("ACCOUNT_ID"), str(exc)[:200]))
            continue
        profiles.append(p)
        enr.append(e)
        att.append(a)
        csat.append(c)
    if errors:
        raise RuntimeError(f"row factory failed on {len(errors)} accounts; first 3: {errors[:3]}")
    return profiles, att, csat, enr


# Columns that may legitimately be constant across the book: CHURNED_C is always 'No', keys are unique ids.
_sp_DEGENERACY_SKIP = {"ATTRITION": ("CHURNED_C", "UNIQUEID"), "CSAT": ("ACCOUNTID",)}


def _sp_degenerate(label: str, columns: tuple, rows: list[dict]) -> list[str]:
    """Model-input columns holding one value across the whole book (a broken feed or formula)."""
    if len(rows) < 2:
        return []
    skip = _sp_DEGENERACY_SKIP[label]
    out = []
    for c in columns:
        if c in skip:
            continue
        values = {r.get(c) for r in rows}
        if len(values) == 1:
            out.append(f"{label}: column {c} is constant ({next(iter(values))!r}) across {len(rows)} rows")
    return out


def gate_problems(profiles, att, csat, enr, run_ts) -> list[str]:
    """Every in-memory gate; an empty list means the rows may be written."""
    out: list[str] = []
    for r in att:
        out.extend(row_problems("ATTRITION", r))
    for r in csat:
        out.extend(row_problems("CSAT", r))
    out.extend(enrollment_problems(enr, profiles))
    out.extend(cross_table_problems(att, csat, enr))
    for label, rows, key in (("ATTRITION", att, "UNIQUEID"), ("CSAT", csat, "ACCOUNTID"),
                             ("ENROLLMENTS", enr, "ACCOUNTID")):
        keys = [r.get(key) for r in rows]
        if len(set(keys)) != len(keys):
            out.append(f"{label}: {len(keys) - len(set(keys))} duplicate {key} values")
    snap = f"{run_ts:%Y-%m}-01 00:00:00"
    off = [r.get("ACCOUNTID") for r in enr if r.get("SNAPSHOT_DATE") != snap]
    if off:
        out.append(f"ENROLLMENTS: {len(off)} rows with SNAPSHOT_DATE other than {snap}; first 3: {off[:3]}")
    out.extend(_sp_degenerate("ATTRITION", ATTRITION_COLUMNS, att))
    out.extend(_sp_degenerate("CSAT", CSAT_COLUMNS, csat))
    return out


def _sp_stage(session, table: str, columns: tuple, rows: list[dict]) -> str:
    """write_pandas into <table>_STAGING (DDL: must run before BEGIN). Returns the staging name."""
    import pandas as pd

    staging = table + "_STAGING"
    session.write_pandas(
        pd.DataFrame(rows, columns=list(columns)), staging.split(".")[-1], database=_sp_DB, schema=_sp_SCHEMA,
        auto_create_table=True, overwrite=True,
    )
    return staging


def _sp_select_list(columns: tuple) -> str:
    # SNAPSHOT_DATE is staged as a string; the target column is TIMESTAMP_NTZ.
    return ", ".join("TO_TIMESTAMP_NTZ(SNAPSHOT_DATE)" if c == "SNAPSHOT_DATE" else c for c in columns)


def replace_tables(session, writes, check=None) -> int:
    """All-or-nothing replace of every target: stage all, then one BEGIN; DELETE + INSERT...SELECT
    per table; optional check(session) inside the transaction; COMMIT. ROLLBACK on any error.
    writes: [(table, columns, rows), ...]. Staging tables are dropped in finally, best-effort."""
    staged: list[str] = []
    try:
        for table, columns, rows in writes:
            staged.append(table + "_STAGING")
            _sp_stage(session, table, columns, rows)
        session.sql("BEGIN").collect()
        try:
            for table, columns, _ in writes:
                cols = ", ".join(columns)
                session.sql(f"DELETE FROM {table}").collect()
                session.sql(
                    f"INSERT INTO {table} ({cols}) SELECT {_sp_select_list(columns)} FROM {table}_STAGING"
                ).collect()
            if check is not None:
                check(session)
            session.sql("COMMIT").collect()
        except Exception:
            try:
                session.sql("ROLLBACK").collect()
            except Exception:
                pass  # never mask the original failure
            raise
    finally:
        for staging in staged:
            try:
                session.sql(f"DROP TABLE IF EXISTS {staging}").collect()
            except Exception:
                pass  # cleanup must not mask the original failure
    return sum(len(rows) for _, _, rows in writes)


def _sp_scalar(session, sql: str) -> int:
    return int(session.sql(sql).collect()[0][0] or 0)


def assert_inputs(session) -> None:
    """Per table: coverage vs the live audience, duplicate keys, key prefix, row count, NULLs."""
    expected_sql = f"WITH {_sp_AUD} SELECT COUNT(*) FROM aud"
    tables = (
        ("attrition", _sp_ATT, "UNIQUEID", ATTRITION_COLUMNS),
        ("csat", _sp_CSAT, "ACCOUNTID", CSAT_COLUMNS),
        ("enrollments", _sp_ENR, "ACCOUNTID", ENROLLMENT_COLUMNS),
    )
    for label, table, key, columns in tables:
        assert_coverage(session, expected_sql, f"SELECT COUNT(DISTINCT {key}) FROM {table}")
        dups = _sp_scalar(session, f"SELECT COUNT(*) - COUNT(DISTINCT {key}) FROM {table}")
        if dups:
            raise RuntimeError(f"coverage gap: {label} has {dups} duplicate {key} rows")
        bad = _sp_scalar(session, f"SELECT COUNT(*) FROM {table} WHERE {key} NOT LIKE '001am%'")
        if bad:
            raise RuntimeError(f"coverage gap: {label} has {bad} keys not LIKE '001am%'")
        aud_n = _sp_scalar(session, expected_sql)
        rows_n = _sp_scalar(session, f"SELECT COUNT(*) FROM {table}")
        if rows_n > aud_n:
            raise RuntimeError(f"coverage gap: {label} has {rows_n} rows, audience has {aud_n}")
        nulls = " + ".join(f"COUNT_IF({c} IS NULL)" for c in columns)
        n = _sp_scalar(session, f"SELECT {nulls} FROM {table}")
        if n:
            raise RuntimeError(f"NULL values: {label} has {n} NULL cells")


def main(session, mode: str = "INPUTS") -> str:
    mode = (mode or "").upper()
    if mode not in _sp_MODES:
        raise ValueError(f"mode must be one of {_sp_MODES}, got {mode!r}")

    started = datetime.now(timezone.utc).replace(tzinfo=None)
    run_ts = started
    log_id = str(uuid.uuid4())
    status, err = "SUCCEEDED", None
    rows_inserted = accounts_processed = grounded = 0
    try:
        features = dedupe_anchors([_sp_to_dict(r) for r in session.sql(FEATURES_SQL).collect()])
        accounts_processed = len(features)
        if not features:
            raise RuntimeError("empty audience: feature query returned no accounts")

        # Build every row and pass every gate before any staging or DML.
        profiles, att, csat, enr = _sp_build_all(features, run_ts)
        # feed coverage: accounts with real FINANCIAL_TRANSACTION_ACCOUNTS holdings vs seeded fallbacks
        grounded = sum(1 for p in profiles if p["grounded"])
        problems = gate_problems(profiles, att, csat, enr, run_ts)
        if problems:
            raise RuntimeError(f"input gate failed with {len(problems)} problems; first 3: {problems[:3]}")

        writes = [(_sp_ATT, ATTRITION_COLUMNS, att), (_sp_CSAT, CSAT_COLUMNS, csat),
                  (_sp_ENR, ENROLLMENT_COLUMNS, enr)]
        rows_inserted = replace_tables(session, writes, check=assert_inputs)
    except Exception as exc:
        status = "FAILED"
        err = str(exc)[:4000]
        raise
    finally:
        duration_ms = int((datetime.now(timezone.utc).replace(tzinfo=None) - started).total_seconds() * 1000)
        session.sql(
            """
            INSERT INTO DATA_JEDAIS.FINS__PUBLIC.TASK_EXECUTION_LOG
                (LOG_ID, TASK_NAME, EXECUTION_TIME, STATUS, ROWS_INSERTED,
                 ACCOUNTS_PROCESSED, ERROR_MESSAGE, DURATION_MS)
            VALUES (?, ?, ?, ?, ?, ?, NULLIF(?, ''), ?)
            """,
            # Snowpark binds a None param as the string 'None', so pass '' and let NULLIF make it NULL.
            params=[log_id, f"{TASK_NAME}[{mode}]", started, status, rows_inserted, accounts_processed,
                    err or "", duration_ms],
        ).collect()

    return f"{TASK_NAME}: {status} rows={rows_inserted} accounts={accounts_processed} grounded={grounded}"
$$;
